-- Initial Order Service schema.
-- UUID values are generated by the application.

CREATE TABLE orders
(
    id                    UUID PRIMARY KEY,
    customer_id           UUID           NOT NULL,

    delivery_address      VARCHAR(500)   NOT NULL,
    delivery_city         VARCHAR(150)   NOT NULL,
    delivery_postal_code  VARCHAR(20),
    delivery_country_code CHAR(2)        NOT NULL,

    total_amount          NUMERIC(12, 2) NOT NULL,
    currency              CHAR(3)        NOT NULL,

    eta_minutes           INTEGER,
    status                VARCHAR(40)    NOT NULL DEFAULT 'NEW',

    created_at            TIMESTAMPTZ    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at            TIMESTAMPTZ    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    version               BIGINT         NOT NULL DEFAULT 0,

    CONSTRAINT chk_orders_total_amount
        CHECK (total_amount >= 0),
    CONSTRAINT chk_orders_currency
        CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT chk_orders_country_code
        CHECK (delivery_country_code ~ '^[A-Z]{2}$'),
    CONSTRAINT chk_orders_eta
        CHECK (eta_minutes IS NULL OR eta_minutes >= 0),
    CONSTRAINT chk_orders_version
        CHECK (version >= 0),
    CONSTRAINT chk_orders_status
        CHECK (status IN (
                          'NEW',
                          'PROCESSING',
                          'CONFIRMED',
                          'IN_DELIVERY',
                          'DELIVERY_FAILED',
                          'RETURNING',
                          'DELIVERED',
                          'CANCEL_REQUESTED',
                          'CANCELLED',
                          'RETURNED'
            ))
);

CREATE INDEX idx_orders_customer_id
    ON orders (customer_id);

CREATE INDEX idx_orders_status
    ON orders (status);

CREATE INDEX idx_orders_created_at
    ON orders (created_at DESC);


CREATE TABLE order_items
(
    id         UUID PRIMARY KEY,
    order_id   UUID           NOT NULL,

    item_name  VARCHAR(255)   NOT NULL,
    quantity   INTEGER        NOT NULL,
    unit_price NUMERIC(12, 2) NOT NULL,
    position   INTEGER        NOT NULL,

    CONSTRAINT fk_order_items_order
        FOREIGN KEY (order_id)
            REFERENCES orders (id)
            ON DELETE CASCADE,

    CONSTRAINT chk_order_items_name
        CHECK (LENGTH(TRIM(item_name)) > 0),
    CONSTRAINT chk_order_items_quantity
        CHECK (quantity > 0),
    CONSTRAINT chk_order_items_unit_price
        CHECK (unit_price >= 0),
    CONSTRAINT chk_order_items_position
        CHECK (position >= 0),
    CONSTRAINT uq_order_items_order_position
        UNIQUE (order_id, position)
);

CREATE INDEX idx_order_items_order_id
    ON order_items (order_id);
